import{_ as t,c as o,o as a,a3 as i}from"./chunks/framework.czLORLkK.js";const A=JSON.parse('{"title":"SyncAPIM: AI 자율 API 보안 관제 및 명세 거버넌스 플랫폼","description":"SyncAPIM은 실시간 API 트래픽 수집, 미등록 섀도우 API 자동 발견, OpenAPI 3.0.1 명세 드리프트 진단, 지능형 웹·API 공격 차단(WAF) 및 민감정보 실시간 마스킹을 제공하는 엔터프라이즈 API 보안·모니터링 에이전트 플랫폼입니다.","frontmatter":{"title":"SyncAPIM: AI 자율 API 보안 관제 및 명세 거버넌스 플랫폼","sidebarTitle":"개요","description":"SyncAPIM은 실시간 API 트래픽 수집, 미등록 섀도우 API 자동 발견, OpenAPI 3.0.1 명세 드리프트 진단, 지능형 웹·API 공격 차단(WAF) 및 민감정보 실시간 마스킹을 제공하는 엔터프라이즈 API 보안·모니터링 에이전트 플랫폼입니다.","head":[["meta",{"name":"keywords","content":"SyncAPIM, API 모니터링, API 보안, WAF, 섀도우 API 탐지, OpenAPI 3.0 스펙 진단, 개인정보 마스킹, JWT 검증, SQL 인젝션 차단, SSRF 방어, AgentScope Java, PostgreSQL 18.6"}],["meta",{"property":"og:title","content":"SyncAPIM: AI 자율 API 보안 관제 및 명세 거버넌스 플랫폼"}],["meta",{"property":"og:description","content":"SyncAPIM은 실시간 API 트래픽 수집, 미등록 섀도우 API 자동 발견, OpenAPI 3.0.1 명세 드리프트 진단, 지능형 웹·API 공격 차단(WAF) 및 민감정보 실시간 마스킹을 제공합니다."}],["meta",{"property":"og:image","content":"https://doc.empasy.com/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/syncapim/"}],["link",{"rel":"canonical","href":"https://doc.empasy.com/syncapim/"}]],"sort":1},"headers":[],"relativePath":"syncapim/index.md","filePath":"ko/syncapim/index.md","lastUpdated":1794045358000}'),c={name:"syncapim/index.md"};function n(r,e,d,s,l,p){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="syncapim-ai-자율-api-보안-관제-및-명세-거버넌스-플랫폼" tabindex="-1">SyncAPIM: AI 자율 API 보안 관제 및 명세 거버넌스 플랫폼 <a class="header-anchor" href="#syncapim-ai-자율-api-보안-관제-및-명세-거버넌스-플랫폼" aria-label="Permalink to “SyncAPIM: AI 자율 API 보안 관제 및 명세 거버넌스 플랫폼”">​</a></h1><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p><strong>SyncSeries 4-Tier API 보안·관제 에이전트 (<code>SYNC_APIM</code>)</strong>: <code>SyncAPIM</code>은 마이크로서비스 및 레거시 WAS 앞단에서 유통되는 모든 API 트래픽을 실시간 수집하여 <strong>미등록 섀도우 API 자동 카탈로그화</strong>, <strong>OpenAPI 3.0.1 명세 드리프트 진단</strong>, <strong>6대 핵심 웹·API 공격 실시간 차단</strong>, <strong>8대 개인·금융 민감정보 동적 마스킹</strong>을 자율 수행합니다.</p></div><h2 id="_1-핵심-아키텍처-및-기술-표준" tabindex="-1">1. 핵심 아키텍처 및 기술 표준 <a class="header-anchor" href="#_1-핵심-아키텍처-및-기술-표준" aria-label="Permalink to “1. 핵심 아키텍처 및 기술 표준”">​</a></h2><ul><li><strong>표준 네임스페이스 및 API</strong>: <code>com.empasy.sync.apim</code> / Canonical API Prefix <code>/api/v1/apim/...</code></li><li><strong>성능 격리형 4-JVM 멀티 프로세스 아키텍처</strong>: <ol><li><code>sync-apim-admin</code> (포트 <code>18089</code> / <code>8080</code>): 통합 관리 콘솔 REST API, 시계열 통계 배치(<code>ApimTrafficAggregationService</code>), <code>SyncApimAgent</code> 및 MCP 서버(<code>/api/v1/apim/mcp</code>)</li><li><code>sync-apim-receiver</code> (포트 <code>18090</code> / <code>8081</code>, TCP <code>5044</code>/<code>5055</code>): Java 25 Virtual Threads 기반 초고속 Lumberjack/Packetbeat 패킷 수신 및 Redis Stream(<code>job_queue</code>) 프로듀서</li><li><code>sync-apim-detector</code> (포트 <code>18092</code> / <code>8090</code>): Redis Stream 컨슈머 워커, OpenAPI 3.0.1 스키마 자동 추론, 6종 WAF 위협 탐지, 8종 PII 마스킹 및 PostgreSQL 18.6 적재</li><li><code>sync-apim-gateway</code> (포트 <code>18091</code> / <code>8083</code>): DB/Redis 실시간 연동 동적 API 차단 필터(<code>BlockedApiFilter</code>) 및 인라인 리버스 프록시 게이트웨이</li></ol></li><li><strong>AI 자율 에이전트 프레임워크</strong>: <code>AgentScope Java</code> (<code>io.agentscope:agentscope-harness</code>) 기반 스펙 드리프트 진단 및 위협 패킷 포렌식 해설</li><li><strong>PostgreSQL 18.6 단일 고성능 스토리지</strong>: 무거운 외부 OpenSearch 클러스터를 제거하고 PostgreSQL 18.6 <code>JSONB</code> + <code>pg_trgm</code> GIN 인덱스 기반 시계열 위협·트래픽 이벤트(<code>wapf_detect_event</code>) 엔진으로 통합</li><li><strong>동적 RBAC 메뉴 거버넌스</strong>: Vben Admin <code>PermissionModeEnum.BACK</code> 모드와 <code>sys_permission</code> 단일 원천 DB를 통해 11개 관제 화면을 역할별로 동적 공급</li></ul><h2 id="_2-주요-기능-구성" tabindex="-1">2. 주요 기능 구성 <a class="header-anchor" href="#_2-주요-기능-구성" aria-label="Permalink to “2. 주요 기능 구성”">​</a></h2><h3 id="_2-1-api-모니터링-perm-apim-000" tabindex="-1">2.1 API 모니터링 (<code>perm-apim-000</code>) <a class="header-anchor" href="#_2-1-api-모니터링-perm-apim-000" aria-label="Permalink to “2.1 API 모니터링 (perm-apim-000)”">​</a></h3><ol><li><strong>호스트 관제 (<code>/waf/host</code>)</strong>: 보호 대상 API 게이트웨이, WAS, 웹서버 호스트 인벤토리 등록 및 수집 에이전트 연결 상태 관제</li><li><strong>API 카탈로그 (<code>/waf/endpoint</code>)</strong>: 실트래픽 패킷 분석을 통한 API 엔드포인트 자동 발견, 위험도 점수 산출 및 원클릭 즉시 차단 제어</li><li><strong>API 스펙 진단 (<code>/waf/api_test</code>)</strong>: OpenAPI 3.0.1 명세서 대비 실제 요청·응답 스키마 불일치(Contract Drift) 및 미승인 섀도우 API 자동 판별</li><li><strong>트래픽 통계 (<code>/waf/api_statistics</code>)</strong>: 엔드포인트별 시계열 호출량, 호스트별 상위 호출 분포 및 엑셀 내보내기/가져오기 지원</li><li><strong>수집 에이전트 (<code>/waf/agent</code>)</strong>: 서비스 도메인별 트래픽 수집 에이전트 SHA-256 인증키 발급 및 대상 호스트 매핑 관리</li></ol><h3 id="_2-2-api-보안-방어-perm-apim-100" tabindex="-1">2.2 API 보안 방어 (<code>perm-apim-100</code>) <a class="header-anchor" href="#_2-2-api-보안-방어-perm-apim-100" aria-label="Permalink to “2.2 API 보안 방어 (perm-apim-100)”">​</a></h3><ol><li><strong>위협 탐지 로그 (<code>/waf/request</code>)</strong>: SQL Injection, XSS, SSRF, RCE, Directory Traversal, JWT 서명 위변조 등 실시간 위협 패킷 원문 및 차단 여부 포렌식 조회</li><li><strong>보안 정책 (<code>/waf/policy</code>)</strong>: 인증, 접근제어, 데이터 암호화, 권한 인가, 네트워크 보안, 개인정보 보호, 침입 탐지 등 7대 표준 보안 정책 그룹 운영 (변경 즉시 Redis 캐시 동기화)</li><li><strong>탐지 룰 관리 (<code>/waf/rule</code>)</strong>: 정규식 시그니처 패턴 및 JWT 무결성 검증 옵션 정의</li><li><strong>위협 룰 통계 (<code>/waf/rule_statistics</code>)</strong>: 공격 유형 및 심각도 등급별 시계열 탐지 추이 및 상위 공격 룰 차트 분석</li><li><strong>민감정보 마스킹 (<code>/waf/sensitivity</code>)</strong>: 계좌번호, 이메일, 카드번호, 주민등록번호, 이름, 비밀번호, IP 주소, 전화번호 등 8대 민감정보 실시간 마스킹 규칙 관리</li><li><strong>경보 메일 이력 (<code>/waf/warning_mails</code>)</strong>: 고위험 공격 차단 및 섀도우 API 발견 시 보안 담당자 경보 발송 이력 추적</li></ol><h2 id="_3-문서-구성-안내" tabindex="-1">3. 문서 구성 안내 <a class="header-anchor" href="#_3-문서-구성-안내" aria-label="Permalink to “3. 문서 구성 안내”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">문서명</th><th style="text-align:left;">주요 다루는 내용</th><th style="text-align:left;">바로가기</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>4-JVM 아키텍처 &amp; DB 설계</strong></td><td style="text-align:left;">4개 독립 JVM 프로세스 분리 구조, Redis Stream 파이프라인, PostgreSQL 18.6 17개 도메인 테이블 상세 명세</td><td style="text-align:left;"><a href="/syncapim/architecture">아키텍처 보기 →</a></td></tr><tr><td style="text-align:left;"><strong>WAF 위협 탐지 &amp; PII 마스킹</strong></td><td style="text-align:left;">섀도우 API 탐지, OpenAPI 3.0.1 Contract Drift 비교 감사, 6대 공격 탐지 룰 및 8대 민감정보 마스킹 정책</td><td style="text-align:left;"><a href="/syncapim/waf-and-pii-governance">보안 거버넌스 보기 →</a></td></tr><tr><td style="text-align:left;"><strong>MCP 도구 &amp; REST API</strong></td><td style="text-align:left;"><code>SyncVerse</code> 관제탑 연동 6대 MCP 도구(<code>apim_discover_shadow_apis</code> 등) 및 <code>/api/v1/apim</code> REST API 레퍼런스</td><td style="text-align:left;"><a href="/syncapim/mcp-tools">MCP &amp; API 보기 →</a></td></tr><tr><td style="text-align:left;"><strong>도입 FAQ</strong></td><td style="text-align:left;">온프레미스 폐쇄망 구축, 4-JVM 성능 격리, OpenSearch 대체 아키텍처 등 자주 묻는 질문</td><td style="text-align:left;"><a href="/syncapim/enterprise-faq">FAQ 보기 →</a></td></tr></tbody></table>',11)])])}const m=t(c,[["render",n]]);export{A as __pageData,m as default};
